      'Last Updated: September 2026': 'अंतिम अपडेट: सितंबर 2026',
      '1. Information We Collect': '1. हम जो जानकारी एकत्र करते हैं',
      'We collect personal details such as your name, email, contact number, and regional farming preferences to provide tailored agricultural courses and advisory services.': 'अनुकूलित कृषि पाठ्यक्रम और सलाहकार सेवाएं प्रदान करने के लिए हम आपका नाम, ईमेल, संपर्क नंबर और क्षेत्रीय खेती प्राथमिकताएं जैसे व्यक्तिगत विवरण एकत्र करते हैं।',
      '2. How We Use Your Data': '2. हम आपके डेटा का उपयोग कैसे करते हैं',
      'Your data is utilized solely for course enrollment, certificate generation, peer community networking, and app performance improvements. We never sell your personal information to third parties.': 'आपके डेटा का उपयोग केवल पाठ्यक्रम नामांकन, प्रमाणपत्र निर्माण, सहकर्मी समुदाय नेटवर्किंग और ऐप प्रदर्शन में सुधार के लिए किया जाता है। हम आपकी व्यक्तिगत जानकारी कभी भी तीसरे पक्षों को नहीं बेचते हैं।',
      '3. Payment Security': '3. भुगतान सुरक्षा',
      'All transactions are processed through encrypted financial gateways conforming to PCI-DSS standards. We do not store credit card or bank account credentials on our servers.': 'सभी लेन-देन PCI-DSS मानकों के अनुरूप एन्क्रिप्टेड वित्तीय गेटवे के माध्यम से संसाधित किए जाते हैं। हम अपने सर्वर पर क्रेडिट कार्ड या बैंक खाते के क्रेडेंशियल संग्रहीत नहीं करते हैं।',
      '4. Your Choices & Controls': '4. आपकी पसंद और नियंत्रण',
      'You retain complete control over your public profile visibility, activity status, and direct messaging privileges through this Privacy Settings tab.': 'आप इस गोपनीयता सेटिंग्स टैब के माध्यम से अपनी सार्वजनिक प्रोफ़ाइल दृश्यता, गतिविधि स्थिति और सीधे संदेश भेजने के विशेषाधिकारों पर पूर्ण नियंत्रण बनाए रखते हैं।',
      'Privacy preference saved': 'गोपनीयता प्राथमिकता सहेजी गई',
      'Manage Your Privacy': 'अपनी गोपनीयता प्रबंधित करें',
