    'mr': {
      'Start Your Farming Community': 'तुमचा शेती समुदाय सुरू करा',
      'Connect directly with local farmers and students in your district. Run updates, broadcast webinars, announce courses, and organize physical farmer meetups!': 'तुमच्या जिल्ह्यातील स्थानिक शेतकरी आणि विद्यार्थ्यांशी थेट जोडले जा. अपडेट्स द्या, वेबिनार प्रसारित करा, अभ्यासक्रमांची घोषणा करा आणि प्रत्यक्ष शेतकरी मेळावे आयोजित करा!',
      'Create Community & Launch': 'समुदाय तयार करा आणि लाँच करा',
      'What you can do in your Community:': 'तुम्ही तुमच्या समुदायात काय करू शकता:',
      '1. General Posts & Crop Tips': '१. सामान्य पोस्ट आणि पीक टिप्स',
      'Publish text guidance and image updates directly into your district feed.': 'तुमच्या जिल्ह्याच्या फीडमध्ये थेट मजकूर मार्गदर्शन आणि प्रतिमा अपडेट्स प्रकाशित करा.',
      '2. Course Announcements': '२. अभ्यासक्रमाच्या घोषणा',
      'Promote live courses with deep links, thumbnail banners, and instant enrollment buttons.': 'थेट अभ्यासक्रमांचा डीप लिंक्स, थंबनेल बॅनर्स आणि त्वरित नोंदणी बटणांसह प्रचार करा.',
