      '1. Information We Collect': '१. आम्ही गोळा करत असलेली माहिती',
      'We collect personal details such as your name, email, contact number, and regional farming preferences to provide tailored agricultural courses and advisory services.': 'अनुकूलित कृषी अभ्यासक्रम आणि सल्लागार सेवा प्रदान करण्यासाठी आम्ही तुमचे नाव, ईमेल, संपर्क क्रमांक आणि प्रादेशिक शेती प्राधान्ये यासारखे वैयक्तिक तपशील गोळा करतो.',
      '2. How We Use Your Data': '२. आम्ही तुमचा डेटा कसा वापरतो',
      'Your data is utilized solely for course enrollment, certificate generation, peer community networking, and app performance improvements. We never sell your personal information to third parties.': 'तुमच्या डेटाचा वापर केवळ अभ्यासक्रम नोंदणी, प्रमाणपत्र निर्मिती, समुदाय नेटवर्किंग आणि अ‍ॅप कार्यप्रदर्शन सुधारण्यासाठी केला जातो. आम्ही तुमची वैयक्तिक माहिती तृतीय पक्षांना कधीही विकत नाही.',
      '3. Payment Security': '३. पेमेंट सुरक्षा',
      'All transactions are processed through encrypted financial gateways conforming to PCI-DSS standards. We do not store credit card or bank account credentials on our servers.': 'सर्व व्यवहार PCI-DSS मानकांशी सुसंगत एन्क्रिप्टेड वित्तीय गेटवेद्वारे प्रक्रिया केले जातात. आम्ही आमच्या सर्व्हरवर क्रेडिट कार्ड किंवा बँक खाते क्रेडेंशियल संचयित करत नाही.',
      '4. Your Choices & Controls': '४. तुमच्या निवडी आणि नियंत्रणे',
      'You retain complete control over your public profile visibility, activity status, and direct messaging privileges through this Privacy Settings tab.': 'तुम्ही या गोपनीयता सेटिंग्ज टॅबद्वारे तुमच्या सार्वजनिक प्रोफाइलची दृश्यता, क्रियाकलाप स्थिती आणि थेट संदेश पाठवण्याच्या अधिकारांवर पूर्ण नियंत्रण ठेवू शकता.',
      'Privacy preference saved': 'गोपनीयता प्राधान्य जतन केले',
      'Manage Your Privacy': 'तुमची गोपनीयता व्यवस्थापित करा',
